import React from 'react';
import { FormDrawer, FormItem, FormLayout, Input, Submit, Reset, FormButtonGroup } from '@storage-fe/formily-arco';
import { createSchemaField } from '@formily/react';
import { Button } from '@arco-design/web-react';

const SchemaField = createSchemaField({
  components: {
    FormItem,
    Input,
  },
});

export default () => (
  <Button
    onClick={() => {
      FormDrawer('抽屉表单', () => (
        <FormLayout labelCol={6} wrapperCol={10}>
          <SchemaField>
            <SchemaField.String name="aaa" required title="输入框1" x-decorator="FormItem" x-component="Input" />
            <SchemaField.String name="bbb" required title="输入框2" x-decorator="FormItem" x-component="Input" />
            <SchemaField.String name="ccc" required title="输入框3" x-decorator="FormItem" x-component="Input" />
            <SchemaField.String name="ddd" required title="输入框4" x-decorator="FormItem" x-component="Input" />
          </SchemaField>
          <FormDrawer.Extra>
            <div>title 额外</div>
          </FormDrawer.Extra>
        </FormLayout>
      ))
        .forOpen((props, next) => {
          setTimeout(() => {
            next();
          }, 1000);
        })
        .forConfirm((payload, next) => {
          setTimeout(() => {
            console.log(payload);
            next(payload);
          }, 1000);
        })
        .open({
          initialValues: {
            aaa: '123',
          },
        })
        .then(console.log);
    }}
  >
    点我打开表单
  </Button>
);
